Use the active sheet as the answer sheet. Combine the two vertical criteria into one row match and the two horizontal criteria into one column match, then read the corresponding value from the data table. Write that plain value to AE5.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals.active
ws = wb.active

def clean(x):
    if x is None:
        return None
    if isinstance(x, str):
        s = x.strip()
        return s if s != "" else None
    return x

def as_number(x):
    if isinstance(x, bool):
        return None
    if isinstance(x, (int, float)):
        return float(x)
    if isinstance(x, str):
        s = x.strip()
        if s == "":
            return None
        try:
            return float(s)
        except ValueError:
            return None
    return None

def same(a, b):
    a = clean(a)
    b = clean(b)
    if a is None or b is None:
        return a is None and b is None
    na = as_number(a)
    nb = as_number(b)
    if na is not None and nb is not None:
        return na == nb
    return str(a).strip() == str(b).strip()

grade = vws["AE4"].value
flute = vws["AD4"].value
qty = vws["AB4"].value
prefix = vws["AC4"].value

row_idx = None
for r in range(5, 11):
    if same(vws.cell(row=r, column=1).value, grade) and same(vws.cell(row=r, column=2).value, flute):
        row_idx = r - 4
        break

col_idx = None
for c in range(3, 27):
    if same(vws.cell(row=3, column=c).value, qty) and same(vws.cell(row=4, column=c).value, prefix):
        col_idx = c - 2
        break

result = None
if row_idx is not None and col_idx is not None:
    result = vws.cell(row=4 + row_idx, column=2 + col_idx).value
    if isinstance(result, str):
        result = result.strip()
    if isinstance(result, float) and result.is_integer():
        result = int(result)

ws["AE5"] = result
wb.save(OUT)

print("criteria:", qty, prefix, flute, grade)
print("row_idx:", row_idx, "col_idx:", col_idx, "result:", result)
